  ('module-06', 'ภารกิจความรู้ ต้องได้ 70% จึงจะผ่าน ทำซ้ำได้ ไม่จำกัด และ ระบบเก็บ ประวัติคะแนน ไว้ หากไม่ผ่าน ไห้ทบทวน บทเรียน ของโมดูลนี้', 'Knowledge Mission: you need 70% to pass. You can retry as often as you like, and the system keeps your score history. If you do not pass, review the Lessons in this Module.'),
  ('module-07', 'ภารกิจความรู้ ต้องได้ 70% จึงจะผ่าน ทำซ้ำได้ ไม่จำกัด และ ระบบเก็บ ประวัติคะแนน ไว้ หากไม่ผ่าน ไห้ทบทวน บทเรียน ของโมดูลนี้', 'Knowledge Mission: you need 70% to pass. You can retry as often as you like, and the system keeps your score history. If you do not pass, review the Lessons in this Module.')
on conflict (module_key) do update
  set instructions_th = excluded.instructions_th,
      instructions_en = excluded.instructions_en;

-- The questions: 3 per Module x 3 options (a/b/c), exactly one is_correct
-- per question, bilingual prompt/option/explanation/review on EVERY row.
